import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Current Entry as Saved","description":"","frontmatter":{"prev":{"text":"Field Types","link":"/documentation/form-fields/field-types"},"next":{"text":"Form Error Message","link":"/documentation/field-types/advance/form-error-message"}},"headers":[],"relativePath":"documentation/field-types/advance/current-entry-as-saved.md","filePath":"documentation/field-types/advance/current-entry-as-saved.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/advance/current-entry-as-saved.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="current-entry-as-saved" tabindex="-1">Current Entry as Saved <a class="header-anchor" href="#current-entry-as-saved" aria-label="Permalink to “Current Entry as Saved”">​</a></h1><p>The <strong>Current Entry as Saved</strong> field type marks the active spreadsheet row as completed based on detecting on-screen success messages, DOM elements, or JavaScript alerts without requiring a page redirect or URL validation.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Key Difference from Form Success Response</strong>: Unlike <a href="/documentation/form-response/form-success-response.html">Form Success Response</a>, this field type operates in-place on the active page without requiring a &quot;Success Page URL&quot; or URL matching rule.</p></div><hr><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to Use”">​</a></h2><p>Use this field type when:</p><ul><li>The target application displays a confirmation banner, modal, or status element on the same page (Single Page Applications / AJAX form submissions).</li><li>You want to mark the current <code>.xlsx</code> row as processed and update execution tracking immediately.</li><li>You need to trigger follow-up actions (e.g., clicking a button, running a segment, or reloading the form) upon successful submission.</li></ul><hr><h2 id="field-options" tabindex="-1">Field Options <a class="header-anchor" href="#field-options" aria-label="Permalink to “Field Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Success Response Type</strong></td><td>Detection mechanism used to locate the success indicator.</td></tr><tr><td><strong>Enter Success Message</strong></td><td>Text strings or patterns to match after the form is processed.</td></tr><tr><td><strong>Delay Time Before Run Action</strong></td><td>Waiting period (in milliseconds) before the follow-up action executes.</td></tr><tr><td><strong>Action</strong></td><td>Operation to trigger when the success message matches.</td></tr></tbody></table><hr><h2 id="additional-options" tabindex="-1">Additional Configuration Options <a class="header-anchor" href="#additional-options" aria-label="Permalink to “Additional Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>If excel data is not found then don&#39;t execute the action</strong></td><td>Skips action execution when spreadsheet records are unavailable.</td></tr><tr><td><strong>If last excel entry completed then don&#39;t execute the action</strong></td><td>Halts follow-up execution once the final row of the dataset is processed.</td></tr><tr><td><strong>If there is no Excel data, update only scraper data in Excel</strong></td><td>Updates only scraped fields in the workbook when standalone templates are used.</td></tr><tr><td><strong>Can success message be anything in this element</strong></td><td>Wildcard mode matching any text rendered inside the target element.</td></tr><tr><td><strong>Remove excel column value from current entry?</strong></td><td>Clears the processed value from extension memory after submission.</td></tr><tr><td><strong>Set custom message after success message matched?</strong></td><td>Logs a custom note in extension logs instead of the raw web message.</td></tr></tbody></table><hr><h2 id="success-response-type" tabindex="-1">Success Response Types <a class="header-anchor" href="#success-response-type" aria-label="Permalink to “Success Response Types”">​</a></h2><p>Choose how the extension identifies completion:</p><h3 id="matching-message-in-page" tabindex="-1">1. Matching Message In Page <a class="header-anchor" href="#matching-message-in-page" aria-label="Permalink to “1. Matching Message In Page”">​</a></h3><p>Searches visible page content or a specific DOM container for the success message.</p><ul><li><strong>Message Selector Query</strong> <em>(Optional)</em>: Limits the search scope to a specific banner, toast, or status container.</li></ul><img src="/image/entry-response-05.png" alt="Success Message Detection on Page" style="max-width:480px;border-radius:8px;margin:16px 0;"><hr><h3 id="matching-message-in-alert" tabindex="-1">2. Matching Message In Browser Alert <a class="header-anchor" href="#matching-message-in-alert" aria-label="Permalink to “2. Matching Message In Browser Alert”">​</a></h3><p>Detects success confirmations that appear inside native browser JavaScript <code>alert()</code> dialogs.</p><img src="/image/js-alert-dialog.png" alt="JavaScript Alert Dialog Handling" style="max-width:450px;border-radius:8px;margin:16px 0;"><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Enable <strong>Hide JavaScript Dialog</strong> in <a href="/documentation/settings.html#hide-javascript-dialog">Extension Settings</a> to dismiss confirmation alerts automatically.</p></div><hr><h3 id="matching-message-in-element-value" tabindex="-1">3. Matching Message In Page Element Value <a class="header-anchor" href="#matching-message-in-element-value" aria-label="Permalink to “3. Matching Message In Page Element Value”">​</a></h3><p>Inspects the <code>value</code> attribute of input, hidden, or readonly fields (e.g., an order ID or confirmation input).</p><ul><li><strong>Required Parameter</strong>: <code>Message Selector Query</code> pointing to the target element.</li></ul><hr><h3 id="checking-element-exists" tabindex="-1">4. Checking Element Exists In Page <a class="header-anchor" href="#checking-element-exists" aria-label="Permalink to “4. Checking Element Exists In Page”">​</a></h3><p>Marks the entry as saved whenever a specific element appears in the DOM.</p><ul><li><strong>Required Parameter</strong>: <code>Message Selector Query</code> targeting the success element (e.g., <code>.order-confirmed-checkmark</code>).</li><li><strong>Condition</strong>: The target element must only be mounted or rendered upon successful submission.</li></ul><hr><h2 id="enter-success-message" tabindex="-1">Enter Success Message <a class="header-anchor" href="#enter-success-message" aria-label="Permalink to “Enter Success Message”">​</a></h2><p>Enter the target text strings to match. You can configure multiple candidate phrases; if any phrase matches, the record is marked saved.</p><ul><li><strong>Dynamic Column Variables</strong>: Inject spreadsheet values using <code>{$ColumnName$}</code> tags (e.g., <code>Thank you {$Name$}, your response was recorded</code>).</li><li><strong>Partial Matching</strong>: Providing <code>&quot;Thank you&quot;</code> matches any string containing <code>&quot;Thank you&quot;</code>.</li></ul><img src="/image/entry-response-07.png" alt="Success Message Configuration" style="max-width:480px;border-radius:8px;margin:16px 0;"><hr><h2 id="delay-time-before-run-action" tabindex="-1">Delay Time Before Run Action <a class="header-anchor" href="#delay-time-before-run-action" aria-label="Permalink to “Delay Time Before Run Action”">​</a></h2><p>Specifies a timeout in milliseconds before executing the configured follow-up action.</p><div class="tip custom-block"><p class="custom-block-title">Conversion</p><p><code>1000 milliseconds = 1 second</code></p></div><hr><h2 id="action" tabindex="-1">Follow-up Action Execution <a class="header-anchor" href="#action" aria-label="Permalink to “Follow-up Action Execution”">​</a></h2><p>Select what occurs once the success state is verified:</p><table tabindex="0"><thead><tr><th>Action</th><th>Execution Behavior</th></tr></thead><tbody><tr><td><strong>Redirect to Page</strong></td><td>Navigates the active tab to a designated URL.</td></tr><tr><td><strong>Re-Execute Form</strong></td><td>Restarts the form workflow with the next spreadsheet entry.</td></tr><tr><td><strong>Click on Button</strong></td><td>Dispatches a click on a specified button (e.g., &quot;Submit Another Response&quot;).</td></tr><tr><td><strong>Page Reload</strong></td><td>Refreshes the active browser tab.</td></tr><tr><td><strong>Execute Segment</strong></td><td>Triggers execution of a modular <a href="/documentation/segment.html">Segment</a> routine.</td></tr></tbody></table><hr><h2 id="important-notes" tabindex="-1">Important Execution Rule <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Execution Rule”">​</a></h2><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p><strong>Placement Constraint</strong>: When this field executes, <strong>all subsequent fields below it in the form list are bypassed</strong>. Always place <strong>Current Entry as Saved</strong> at the very bottom of your form field sequence.</p></div><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Field 1: Name Input]           ──&gt; Executes</span></span>
<span class="line"><span>[Field 2: Email Input]          ──&gt; Executes</span></span>
<span class="line"><span>[Field 3: Submit Button]        ──&gt; Executes</span></span>
<span class="line"><span>[Current Entry as Saved]        ──&gt; Marks Row Saved &amp; Triggers Action</span></span>
<span class="line"><span>--------------------------------------------------------------------</span></span>
<span class="line"><span>[Field 4: Any Lower Field]      ──&gt; DOES NOT EXECUTE (Bypassed)</span></span></code></pre></div><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-response/form-success-response.html">Form Success Response</a></li><li><img src="/svg/bug.svg" class="doc-icon"> <a href="/documentation/field-types/advance/form-error-message.html">Form Error Message</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a></li><li><img src="/svg/template.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments Routine Automation</a></li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template (.xlsx)</a></li></ul>`,53)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};